pub fn min_scalar_type(value: i8) -> NumpyDType {
    // Convert input to i64 for convenience in range checks
    let val64 = value as i64;

    // Consider all types of size at least 8 bits (all given types satisfy this)
    // We want:
    //  1) can represent `value`
    //  2) no type with strictly smaller bit-size can represent `value`
    //  3) among types of the same bit-size that can represent `value`,
    //     choose type with smallest kind order

    // We'll enumerate all types, filter by can_represent_value,
    // then pick minimal bit-size, and from those minimal bit-size types pick minimal kind order.

    let all_types = [
        // UInts
        NumpyDType::UInt8,
        NumpyDType::UInt16,
        NumpyDType::UInt32,
        NumpyDType::UInt64,

        // Ints
        NumpyDType::Int8,
        NumpyDType::Int16,
        NumpyDType::Int32,
        NumpyDType::Int64,

        // Floats
        NumpyDType::Float16,
        NumpyDType::Float32,
        NumpyDType::Float64,

        // Complex
        NumpyDType::Complex64,
        NumpyDType::Complex128,
    ];

    // Filter to types that can represent value
    let mut candidates: Vec<NumpyDType> = all_types
        .iter()
        .copied()
        .filter(|dt| dt.can_represent_value(val64))
        .collect();

    // Find minimal bit-size among candidates
    let min_bit_size = candidates.iter().map(|dt| dt.dtype_size()).min().unwrap();

    // Restrict candidates to only those with min bit-size
    candidates.retain(|dt| dt.dtype_size() == min_bit_size);

    // From candidates, pick the one with minimal kind order
    candidates.into_iter()
        .min_by_key(|dt| dt.dtype_kind_order())
        .unwrap()
}

